@page "/apply"
@rendermode InteractiveServer
@using sv_301328e27cd4422fa4ca223facbcb75f.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<h1>Job Application</h1>

@* Step Indicator Bar *@
<nav class="step-indicator" aria-label="Application steps">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var stepIndex = i;
        var stepClass = GetStepClass(stepIndex);
        <div class="step @stepClass" @onclick="() => NavigateToStep(stepIndex)" role="button" tabindex="0">
            <div class="step-circle">
                @if (stepIndex < CurrentStep)
                {
                    <span class="checkmark">&#10003;</span>
                }
                else
                {
                    <span>@(stepIndex + 1)</span>
                }
            </div>
            <div class="step-label">@StepNames[stepIndex]</div>
        </div>
        @if (i < StepNames.Length - 1)
        {
            <div class="step-connector @(stepIndex < CurrentStep ? "completed" : "")"></div>
        }
    }
</nav>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger" role="alert">@ErrorMessage</div>
}

@* Step Content *@
<div class="step-content">
    @switch (CurrentStep)
    {
        case 0:
            @* Step 1 — Personal Info *@
            <h2>Personal Information</h2>
            <div class="form-group">
                <label for="fullName">Full Name *</label>
                <input id="fullName" type="text" class="form-control" @bind="FullName" />
            </div>
            <div class="form-group">
                <label for="email">Email *</label>
                <input id="email" type="email" class="form-control" @bind="Email" />
            </div>
            <div class="form-group">
                <label for="phone">Phone *</label>
                <input id="phone" type="tel" class="form-control" @bind="Phone" />
            </div>
            <div class="form-group">
                <label for="address">Address *</label>
                <input id="address" type="text" class="form-control" @bind="Address" />
            </div>
            <div class="step-buttons">
                <button class="btn btn-primary" @onclick="NextStep" disabled="@IsProcessing">
                    @(IsProcessing ? "Validating..." : "Next")
                </button>
            </div>
            break;

        case 1:
            @* Step 2 — Work History *@
            <h2>Work History</h2>
            @for (int i = 0; i < WorkEntries.Count; i++)
            {
                var index = i;
                <fieldset class="work-entry">
                    <legend>Position @(index + 1)</legend>
                    <div class="form-group">
                        <label>Company Name *</label>
                        <input type="text" class="form-control" value="@WorkEntries[index].Company"
                            @onchange="(e) => UpdateWorkEntry(index, nameof(WorkEntryModel.Company), e.Value?.ToString())" />
                    </div>
                    <div class="form-group">
                        <label>Job Title *</label>
                        <input type="text" class="form-control" value="@WorkEntries[index].Title"
                            @onchange="(e) => UpdateWorkEntry(index, nameof(WorkEntryModel.Title), e.Value?.ToString())" />
                    </div>
                    <div class="form-group">
                        <label>Start Date *</label>
                        <input type="date" class="form-control" value="@WorkEntries[index].StartDate?.ToString("yyyy-MM-dd")"
                            @onchange="(e) => UpdateWorkEntryDate(index, true, e.Value?.ToString())" />
                    </div>
                    <div class="form-group">
                        <label>
                            <input type="checkbox" checked="@WorkEntries[index].IsCurrent"
                                @onchange="(e) => ToggleCurrentJob(index, (bool)(e.Value ?? false))" />
                            Currently working here
                        </label>
                    </div>
                    @if (!WorkEntries[index].IsCurrent)
                    {
                        <div class="form-group">
                            <label>End Date</label>
                            <input type="date" class="form-control" value="@WorkEntries[index].EndDate?.ToString("yyyy-MM-dd")"
                                @onchange="(e) => UpdateWorkEntryDate(index, false, e.Value?.ToString())" />
                        </div>
                    }
                    <div class="form-group">
                        <label>Description *</label>
                        <textarea class="form-control" rows="3" value="@WorkEntries[index].Description"
                            @onchange="(e) => UpdateWorkEntry(index, nameof(WorkEntryModel.Description), e.Value?.ToString())"></textarea>
                    </div>
                    @if (WorkEntries.Count > 1)
                    {
                        <button class="btn btn-danger btn-sm" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                    }
                </fieldset>
            }
            <button class="btn btn-secondary" @onclick="AddWorkEntry">Add Another Position</button>
            <div class="step-buttons">
                <button class="btn btn-outline-secondary" @onclick="PreviousStep">Back</button>
                <button class="btn btn-primary" @onclick="NextStep">Next</button>
            </div>
            break;

        case 2:
            @* Step 3 — References *@
            <h2>References</h2>
            @for (int i = 0; i < References.Count; i++)
            {
                var index = i;
                <fieldset class="reference-entry">
                    <legend>Reference @(index + 1)</legend>
                    <div class="form-group">
                        <label>Name *</label>
                        <input type="text" class="form-control" value="@References[index].Name"
                            @onchange="(e) => UpdateReference(index, nameof(ReferenceModel.Name), e.Value?.ToString())" />
                    </div>
                    <div class="form-group">
                        <label>Relationship *</label>
                        <input type="text" class="form-control" value="@References[index].Relationship"
                            @onchange="(e) => UpdateReference(index, nameof(ReferenceModel.Relationship), e.Value?.ToString())" />
                    </div>
                    <div class="form-group">
                        <label>Email *</label>
                        <input type="email" class="form-control" value="@References[index].Email"
                            @onchange="(e) => UpdateReference(index, nameof(ReferenceModel.Email), e.Value?.ToString())" />
                    </div>
                    <div class="form-group">
                        <label>Phone *</label>
                        <input type="tel" class="form-control" value="@References[index].Phone"
                            @onchange="(e) => UpdateReference(index, nameof(ReferenceModel.Phone), e.Value?.ToString())" />
                    </div>
                    @if (References.Count > 2)
                    {
                        <button class="btn btn-danger btn-sm" @onclick="() => RemoveReference(index)">Remove</button>
                    }
                </fieldset>
            }
            @if (References.Count < 3)
            {
                <button class="btn btn-secondary" @onclick="AddReference">Add Reference</button>
            }
            <div class="step-buttons">
                <button class="btn btn-outline-secondary" @onclick="PreviousStep">Back</button>
                <button class="btn btn-primary" @onclick="NextStep">Next</button>
            </div>
            break;

        case 3:
            @* Step 4 — Cover Letter *@
            <h2>Cover Letter</h2>
            <div class="form-group">
                <label for="coverLetter">Write your cover letter *</label>
                <textarea id="coverLetter" class="form-control" rows="12" maxlength="2000"
                    @bind="CoverLetter" @bind:event="oninput"></textarea>
                <div class="character-count">@CoverLetter.Length / 2000 characters</div>
            </div>
            <div class="step-buttons">
                <button class="btn btn-outline-secondary" @onclick="PreviousStep">Back</button>
                <button class="btn btn-primary" @onclick="NextStep">Next</button>
            </div>
            break;

        case 4:
            @* Step 5 — Review & Submit *@
            @if (IsSubmitted)
            {
                <div class="submission-confirmation">
                    <h2>Application Submitted!</h2>
                    <p>Thank you for your application. Your application ID is: <strong>@ApplicationId</strong></p>
                </div>
            }
            else
            {
                <h2>Review &amp; Submit</h2>

                <section class="review-section">
                    <h3>Personal Information <a class="edit-link" @onclick="() => GoToStep(0)">Edit</a></h3>
                    <dl>
                        <dt>Full Name</dt><dd>@FullName</dd>
                        <dt>Email</dt><dd>@Email</dd>
                        <dt>Phone</dt><dd>@Phone</dd>
                        <dt>Address</dt><dd>@Address</dd>
                    </dl>
                </section>

                <section class="review-section">
                    <h3>Work History <a class="edit-link" @onclick="() => GoToStep(1)">Edit</a></h3>
                    @foreach (var entry in WorkEntries)
                    {
                        <div class="review-work-entry">
                            <strong>@entry.Title</strong> at @entry.Company<br />
                            <em>@entry.StartDate?.ToString("MMM yyyy") &mdash; @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))</em>
                            <p>@entry.Description</p>
                        </div>
                    }
                </section>

                <section class="review-section">
                    <h3>References <a class="edit-link" @onclick="() => GoToStep(2)">Edit</a></h3>
                    @foreach (var reference in References)
                    {
                        <div class="review-reference">
                            <strong>@reference.Name</strong> (@reference.Relationship)<br />
                            @reference.Email | @reference.Phone
                        </div>
                    }
                </section>

                <section class="review-section">
                    <h3>Cover Letter <a class="edit-link" @onclick="() => GoToStep(3)">Edit</a></h3>
                    <p class="cover-letter-preview">@CoverLetter</p>
                </section>

                <div class="step-buttons">
                    <button class="btn btn-outline-secondary" @onclick="PreviousStep">Back</button>
                    <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@IsProcessing">
                        @(IsProcessing ? "Submitting..." : "Submit Application")
                    </button>
                </div>
            }
            break;
    }
</div>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int CurrentStep { get; set; }
    private string ErrorMessage { get; set; } = string.Empty;
    private bool IsProcessing { get; set; }
    private bool IsSubmitted { get; set; }
    private int ApplicationId { get; set; }

    // Step 1 fields
    private string FullName { get; set; } = string.Empty;
    private string Email { get; set; } = string.Empty;
    private string Phone { get; set; } = string.Empty;
    private string Address { get; set; } = string.Empty;

    // Step 2 fields
    private List<WorkEntryModel> WorkEntries { get; set; } = new() { new WorkEntryModel() };

    // Step 3 fields
    private List<ReferenceModel> References { get; set; } = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4 fields
    private string CoverLetter { get; set; } = string.Empty;

    private string GetStepClass(int step)
    {
        if (step == CurrentStep) return "active";
        if (step < CurrentStep) return "completed";
        return "future";
    }

    private void NavigateToStep(int step)
    {
        if (step < CurrentStep)
        {
            CurrentStep = step;
            ErrorMessage = string.Empty;
        }
    }

    private void GoToStep(int step)
    {
        CurrentStep = step;
        ErrorMessage = string.Empty;
    }

    private void PreviousStep()
    {
        if (CurrentStep > 0)
        {
            CurrentStep--;
            ErrorMessage = string.Empty;
        }
    }

    private async Task NextStep()
    {
        ErrorMessage = string.Empty;

        if (!ValidateCurrentStep())
            return;

        if (CurrentStep == 0)
        {
            IsProcessing = true;
            try
            {
                var isValidEmail = await ApplicationService.ValidateEmailAsync(Email);
                if (!isValidEmail)
                {
                    ErrorMessage = "The email address is not valid. Please enter a valid email.";
                    return;
                }
            }
            finally
            {
                IsProcessing = false;
            }
        }

        CurrentStep++;
    }

    private bool ValidateCurrentStep()
    {
        switch (CurrentStep)
        {
            case 0:
                if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email) ||
                    string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
                {
                    ErrorMessage = "All fields are required.";
                    return false;
                }
                break;
            case 1:
                foreach (var entry in WorkEntries)
                {
                    if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) ||
                        entry.StartDate == null || string.IsNullOrWhiteSpace(entry.Description))
                    {
                        ErrorMessage = "Please fill in all required fields for each work entry.";
                        return false;
                    }
                }
                break;
            case 2:
                foreach (var reference in References)
                {
                    if (string.IsNullOrWhiteSpace(reference.Name) || string.IsNullOrWhiteSpace(reference.Relationship) ||
                        string.IsNullOrWhiteSpace(reference.Email) || string.IsNullOrWhiteSpace(reference.Phone))
                    {
                        ErrorMessage = "Please fill in all required fields for each reference.";
                        return false;
                    }
                }
                break;
            case 3:
                if (string.IsNullOrWhiteSpace(CoverLetter))
                {
                    ErrorMessage = "Cover letter is required.";
                    return false;
                }
                break;
        }
        return true;
    }

    // Work Entry helpers
    private void AddWorkEntry() => WorkEntries.Add(new WorkEntryModel());

    private void RemoveWorkEntry(int index)
    {
        if (WorkEntries.Count > 1)
            WorkEntries.RemoveAt(index);
    }

    private void UpdateWorkEntry(int index, string field, string? value)
    {
        var entry = WorkEntries[index];
        switch (field)
        {
            case nameof(WorkEntryModel.Company): entry.Company = value ?? string.Empty; break;
            case nameof(WorkEntryModel.Title): entry.Title = value ?? string.Empty; break;
            case nameof(WorkEntryModel.Description): entry.Description = value ?? string.Empty; break;
        }
    }

    private void UpdateWorkEntryDate(int index, bool isStart, string? value)
    {
        if (DateTime.TryParse(value, out var date))
        {
            if (isStart)
                WorkEntries[index].StartDate = date;
            else
                WorkEntries[index].EndDate = date;
        }
    }

    private void ToggleCurrentJob(int index, bool isCurrent)
    {
        WorkEntries[index].IsCurrent = isCurrent;
        if (isCurrent)
            WorkEntries[index].EndDate = null;
    }

    // Reference helpers
    private void AddReference()
    {
        if (References.Count < 3)
            References.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
            References.RemoveAt(index);
    }

    private void UpdateReference(int index, string field, string? value)
    {
        var reference = References[index];
        switch (field)
        {
            case nameof(ReferenceModel.Name): reference.Name = value ?? string.Empty; break;
            case nameof(ReferenceModel.Relationship): reference.Relationship = value ?? string.Empty; break;
            case nameof(ReferenceModel.Email): reference.Email = value ?? string.Empty; break;
            case nameof(ReferenceModel.Phone): reference.Phone = value ?? string.Empty; break;
        }
    }

    // Submit
    private async Task SubmitApplication()
    {
        IsProcessing = true;
        ErrorMessage = string.Empty;

        try
        {
            var personal = new PersonalInfo(FullName, Email, Phone, Address);
            var workHistory = new WorkHistory(WorkEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate ?? DateTime.MinValue, e.IsCurrent ? null : e.EndDate, e.Description)
            ).ToList());
            var references = References.Select(r =>
                new Reference(r.Name, r.Relationship, r.Email, r.Phone)
            ).ToList();

            var application = new JobApplication(personal, workHistory, references, CoverLetter);
            ApplicationId = await ApplicationService.SubmitApplicationAsync(application);
            IsSubmitted = true;
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            IsProcessing = false;
        }
    }

    // Mutable model classes for form binding
    private class WorkEntryModel
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime? StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = string.Empty;
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = string.Empty;
        public string Relationship { get; set; } = string.Empty;
        public string Email { get; set; } = string.Empty;
        public string Phone { get; set; } = string.Empty;
    }
}

