.step.active .step-circle {
    background: #0d6efd;
    color: white;
}

.step.completed .step-circle {
    background: #198754;
    color: white;
}

.step-label {
    font-size: 0.75rem;
    text-align: center;
    max-width: 80px;
}

.step-connector {
    width: 40px;
    height: 2px;
    background: #dee2e6;
    align-self: center;
    margin-bottom: 1.2rem;
}

.step-connector.completed {
    background: #198754;
}

.checkmark {
    font-size: 1rem;
}

.step-content {
    max-width: 700px;
    margin: 0 auto;
    padding: 1.5rem 0;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.3rem;
}

.form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 0.375rem;
    font-size: 1rem;
    box-sizing: border-box;
}

textarea.form-control {
    resize: vertical;
}

.step-buttons {
    display: flex;
    gap: 1rem;
    margin-top: 2rem;
    justify-content: flex-end;
}

.btn {
    padding: 0.5rem 1.25rem;
    border: 1px solid transparent;
    border-radius: 0.375rem;
    font-size: 1rem;
    cursor: pointer;
    text-decoration: none;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-primary {
    background-color: #0d6efd;
    color: white;
}

.btn-primary:hover:not(:disabled) {
    background-color: #0b5ed7;
}

.btn-secondary {
    background-color: #6c757d;
    color: white;
}

.btn-outline-secondary {
    background: transparent;
    border-color: #6c757d;
    color: #6c757d;
}

.btn-danger {
    background-color: #dc3545;
    color: white;
}

.btn-success {
    background-color: #198754;
    color: white;
}

.btn-success:hover:not(:disabled) {
    background-color: #157347;
}

.btn-sm {
    padding: 0.25rem 0.75rem;
    font-size: 0.875rem;
}

.btn-lg {
    padding: 0.75rem 1.5rem;
    font-size: 1.1rem;
}

.alert {
    padding: 0.75rem 1rem;
    border-radius: 0.375rem;
    margin-bottom: 1rem;
}

.alert-danger {
    background-color: #f8d7da;
    color: #842029;
    border: 1px solid #f5c2c7;
}

.work-entry,
.reference-entry {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    padding: 1.25rem;
    margin-bottom: 1rem;
}

.work-entry legend,
.reference-entry legend {
    font-weight: 600;
    font-size: 0.95rem;
